ALTER TABLE pm_master_list DROP CONSTRAINT pm_master_list_duty_type_check; UPDATE pm_master_list SET duty_type = 'Offline' WHERE LOWER(pm_name) LIKE '%offline%'; UPDATE pm_master_list SET duty_type = 'Online' WHERE duty_type IS DISTINCT FROM 'Offline'; ALTER TABLE pm_master_list ADD CONSTRAINT pm_master_list_duty_type_check CHECK (duty_type = ANY (ARRAY['Online'::text, 'Offline'::text]));